// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 // head spheres (2 leaflets)  → InstancedMesh SphereGeometry(0.13,12,9), green #4FBF8F→#8FD9B6
 // hydrocarbon tails          → InstancedMesh TubeGeometry(wavy CatmullRom, r=0.035), tan #D9A38E→#E5BCA9
 // midplane seam              → LineLoop at y=0, #C98F7C
 // glycerol band (highlight)  → 2× thin BoxGeometry at y=±1.0, amber #E8A33D (hidden by default)
 // cutaway                    → 3 THREE.Plane clipping planes, slab drawn as 2 clip-groups (union)
 // cut faces                  → 2× PlaneGeometry caps, pale tan #E5BCA9 + seam strip
 // formula bonds (black)      → merged quad BufferGeometry #1A1A1A
 // formula bonds (green)      → merged quad BufferGeometry #17A06A  (+ P=O, O⁻, arrow)
 // fatty-acyl ribbons         → merged wavy quad strip #D9A38E (width 0.13, 4 waves)
 // magenta arrows             → merged quad+triangle BufferGeometry #E0218A
 // glow overlays              → PlaneGeometry per region, transparent, also click targets
 // all text                   → addLabel (HTML, sub/superscripts)
──────────────────────────────────────────────────────────────────────────── */

renderer.localClippingEnabled = true;
document.getElementById('btnReset').style.display = '';

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.42));
scene.add(new THREE.HemisphereLight(0xffffff, 0xcfd8d2, 0.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-7, 9, 8);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.22);
fillLight.position.set(6, -4, -7);
scene.add(fillLight);

/* ── slab constants ─────────────────────────────────────────────────────── */
const SX = -5.5, NX = 24, NZ = 15, SP = 0.30, HR = 0.13, HY = 1.10, TAILLEN = 1.05;
const XMIN = -9.12, XMAX = -1.76, ZMIN = -2.24, ZMAX = 2.24;

const headGeo = new THREE.SphereGeometry(HR, 12, 9);
const tailPts = [];
for (let i = 0; i <= 8; i++) {
  const u = i / 8;
  tailPts.push(new THREE.Vector3(
    Math.sin(u * Math.PI * 3.0) * 0.08,
    -u * TAILLEN,
    Math.sin(u * Math.PI * 2.2) * 0.035
  ));
}
const tailGeo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(tailPts), 18, 0.035, 5, false);

/* clipping planes: keep  (x<=xCut)  UNION  (x>=xCut AND z<=zCut)  */
const planeA = new THREE.Plane(new THREE.Vector3(-1, 0, 0), XMAX);
const planeB1 = new THREE.Plane(new THREE.Vector3(1, 0, 0), -XMAX);
const planeB2 = new THREE.Plane(new THREE.Vector3(0, 0, -1), ZMAX);

function buildSlab(clips) {
  const grp = new THREE.Group();
  const matHead = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.20, metalness: 0.0,
    side: THREE.DoubleSide, clippingPlanes: clips,
    emissive: 0x000000, emissiveIntensity: 0.55
  });
  const matTail = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.78, metalness: 0.0,
    side: THREE.DoubleSide, clippingPlanes: clips,
    emissive: 0x000000, emissiveIntensity: 0.6
  });
  const N = NX * NZ;
  const o = new THREE.Object3D();
  const cA = new THREE.Color(), cB = new THREE.Color();
  const heads = [], tails = [];

  for (const sgn of [1, -1]) {
    const hm = new THREE.InstancedMesh(headGeo, matHead, N);
    const tm = new THREE.InstancedMesh(tailGeo, matTail, N);
    let k = 0;
    for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++, k++) {
      const x = SX + (i - (NX - 1) / 2) * SP + (j % 2 ? SP / 2 : 0);
      const z = (j - (NZ - 1) / 2) * SP;
      const y = sgn * HY;
      o.position.set(x, y, z);
      o.rotation.set(0, Math.random() * 6.283, 0);
      o.scale.setScalar(0.94 + Math.random() * 0.12);
      o.updateMatrix(); hm.setMatrixAt(k, o.matrix);
      hm.setColorAt(k, cA.set(0x4FBF8F).lerp(cB.set(0x8FD9B6), 0.25 + 0.75 * Math.random()));

      o.position.set(x, y, z);
      o.rotation.set(sgn > 0 ? 0 : Math.PI, Math.random() * 6.283, 0);
      o.scale.setScalar(1);
      o.updateMatrix(); tm.setMatrixAt(k, o.matrix);
      tm.setColorAt(k, cA.set(0xD9A38E).lerp(cB.set(0xE5BCA9), Math.random()));
    }
    hm.instanceMatrix.needsUpdate = true; hm.instanceColor.needsUpdate = true;
    tm.instanceMatrix.needsUpdate = true; tm.instanceColor.needsUpdate = true;
    hm.computeBoundingBox(); tm.computeBoundingBox();
    grp.add(hm, tm); heads.push(hm); tails.push(tm);
  }

  /* midplane seam */
  const seamMat = new THREE.LineBasicMaterial({ color: 0xC98F7C, clippingPlanes: clips, transparent: true, opacity: 0.85 });
  const seam = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(XMIN, 0, ZMIN), new THREE.Vector3(XMAX, 0, ZMIN),
    new THREE.Vector3(XMAX, 0, ZMAX), new THREE.Vector3(XMIN, 0, ZMAX)
  ]), seamMat);
  grp.add(seam);

  /* glycerol interfacial band (highlight only) */
  const bandMat = new THREE.MeshBasicMaterial({
    color: 0xE8A33D, transparent: true, opacity: 0.8,
    side: THREE.DoubleSide, clippingPlanes: clips, depthWrite: false
  });
  const bandGeo = new THREE.BoxGeometry(XMAX - XMIN, 0.10, ZMAX - ZMIN);
  const bands = [];
  for (const sgn of [1, -1]) {
    const b = new THREE.Mesh(bandGeo, bandMat);
    b.position.set((XMIN + XMAX) / 2, sgn * 1.0, 0);
    b.visible = false;
    grp.add(b); bands.push(b);
  }

  scene.add(grp);
  return { grp, matHead, matTail, bands, heads, tails };
}

const slabA = buildSlab([planeA]);
const slabB = buildSlab([planeB1, planeB2]);
const slabs = [slabA, slabB];

/* ── cut-face caps ──────────────────────────────────────────────────────── */
const capMat = new THREE.MeshStandardMaterial({ color: 0xE5BCA9, roughness: 0.92, side: THREE.DoubleSide });
const capSeamMat = new THREE.MeshBasicMaterial({ color: 0xC98F7C, side: THREE.DoubleSide });
function makeCap() {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), capMat);
  const s = new THREE.Mesh(new THREE.PlaneGeometry(1, 0.012), capSeamMat);
  s.position.set(0, 0, 0.003);
  m.add(s);
  scene.add(m);
  return m;
}
const capX = makeCap(); capX.rotation.y = Math.PI / 2;   // faces +X
const capZ = makeCap();                                   // faces +Z

let cutT = 0.35, cutTarget = 0.35;
function applyCut(t) {
  const xCut = XMAX - 2.6 * t;
  const zCut = ZMAX - 1.8 * t;
  planeA.constant = xCut;
  planeB1.constant = -xCut;
  planeB2.constant = zCut;
  const show = t > 0.006;
  capX.visible = capZ.visible = show;
  if (show) {
    capX.position.set(xCut - 0.005, 0, (zCut + ZMAX) / 2);
    capX.scale.set(ZMAX - zCut, 2.06, 1);
    capZ.position.set((xCut + XMAX) / 2, 0, zCut - 0.005);
    capZ.scale.set(XMAX - xCut, 2.06, 1);
  }
  const lab = document.getElementById('cutVal');
