  <button data-part="head">Ionic head</button>
  <button data-part="glycerol">Glycerol linker</button>
  <button data-part="tails">Nonpolar tails</button>
</div>

<label style="margin-top:6px">Cutaway depth: <span id="cutVal">0.35</span>
  <input id="cutaway" type="range" min="0" max="1" step="0.01" value="0.35">
</label>

<div style="font-weight:600;margin-top:6px">Guided tour</div>
<div style="display:flex;gap:4px">
  <button id="btnPrev">◀ Prev</button>
  <button id="btnPlay">▶ Play</button>
  <button id="btnNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:600;margin-top:3px"></div>
<div id="stepNarr" style="line-height:1.35;color:#333"></div>

<div style="color:#666;margin-top:6px;line-height:1.35">
  Drag to orbit the slab. Click the phosphocholine group, the glycerol backbone, or a tan tail
  in the formula (or the matching layer of the slab) to link structure to assembly.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 // head spheres (2 leaflets)  → InstancedMesh SphereGeometry(0.13,12,9), green #4FBF8F→#8FD9B6
 // hydrocarbon tails          → InstancedMesh TubeGeometry(wavy CatmullRom, r=0.035), tan #D9A38E→#E5BCA9
 // midplane seam              → LineLoop at y=0, #C98F7C
 // glycerol band (highlight)  → 2× thin BoxGeometry at y=±1.0, amber #E8A33D (hidden by default)
 // cutaway                    → 3 THREE.Plane clipping planes, slab drawn as 2 clip-groups (union)
 // cut faces                  → 2× PlaneGeometry caps, pale tan #E5BCA9 + seam strip
 // formula bonds (black)      → merged quad BufferGeometry #1A1A1A
 // formula bonds (green)      → merged quad BufferGeometry #17A06A  (+ P=O, O⁻, arrow)
 // fatty-acyl ribbons         → merged wavy quad strip #D9A38E (width 0.13, 4 waves)
 // magenta arrows             → merged quad+triangle BufferGeometry #E0218A
 // glow overlays              → PlaneGeometry per region, transparent, also click targets
 // all text                   → addLabel (HTML, sub/superscripts)
──────────────────────────────────────────────────────────────────────────── */

renderer.localClippingEnabled = true;
document.getElementById('btnReset').style.display = '';

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.42));
scene.add(new THREE.HemisphereLight(0xffffff, 0xcfd8d2, 0.55));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-7, 9, 8);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.22);
fillLight.position.set(6, -4, -7);
scene.add(fillLight);

/* ── slab constants ─────────────────────────────────────────────────────── */
const SX = -5.5, NX = 24, NZ = 15, SP = 0.30, HR = 0.13, HY = 1.10, TAILLEN = 1.05;
const XMIN = -9.12, XMAX = -1.76, ZMIN = -2.24, ZMAX = 2.24;

const headGeo = new THREE.SphereGeometry(HR, 12, 9);
const tailPts = [];
for (let i = 0; i <= 8; i++) {
  const u = i / 8;
  tailPts.push(new THREE.Vector3(
    Math.sin(u * Math.PI * 3.0) * 0.08,
    -u * TAILLEN,
    Math.sin(u * Math.PI * 2.2) * 0.035
  ));
}
const tailGeo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(tailPts), 18, 0.035, 5, false);

/* clipping planes: keep  (x<=xCut)  UNION  (x>=xCut AND z<=zCut)  */
const planeA = new THREE.Plane(new THREE.Vector3(-1, 0, 0), XMAX);
const planeB1 = new THREE.Plane(new THREE.Vector3(1, 0, 0), -XMAX);
const planeB2 = new THREE.Plane(new THREE.Vector3(0, 0, -1), ZMAX);

function buildSlab(clips) {
  const grp = new THREE.Group();
  const matHead = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.20, metalness: 0.0,
    side: THREE.DoubleSide, clippingPlanes: clips,
    emissive: 0x000000, emissiveIntensity: 0.55
  });
  const matTail = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.78, metalness: 0.0,
    side: THREE.DoubleSide, clippingPlanes: clips,
    emissive: 0x000000, emissiveIntensity: 0.6
  });
  const N = NX * NZ;
  const o = new THREE.Object3D();
  const cA = new THREE.Color(), cB = new THREE.Color();
  const heads = [], tails = [];

  for (const sgn of [1, -1]) {
    const hm = new THREE.InstancedMesh(headGeo, matHead, N);
    const tm = new THREE.InstancedMesh(tailGeo, matTail, N);
    let k = 0;
    for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++, k++) {
      const x = SX + (i - (NX - 1) / 2) * SP + (j % 2 ? SP / 2 : 0);
      const z = (j - (NZ - 1) / 2) * SP;
      const y = sgn * HY;
      o.position.set(x, y, z);
      o.rotation.set(0, Math.random() * 6.283, 0);
      o.scale.setScalar(0.94 + Math.random() * 0.12);
      o.updateMatrix(); hm.setMatrixAt(k, o.matrix);
      hm.setColorAt(k, cA.set(0x4FBF8F).lerp(cB.set(0x8FD9B6), 0.25 + 0.75 * Math.random()));

      o.position.set(x, y, z);
      o.rotation.set(sgn > 0 ? 0 : Math.PI, Math.random() * 6.283, 0);
      o.scale.setScalar(1);
      o.updateMatrix(); tm.setMatrixAt(k, o.matrix);
      tm.setColorAt(k, cA.set(0xD9A38E).lerp(cB.set(0xE5BCA9), Math.random()));
    }
    hm.instanceMatrix.needsUpdate = true; hm.instanceColor.needsUpdate = true;
    tm.instanceMatrix.needsUpdate = true; tm.instanceColor.needsUpdate = true;
    hm.computeBoundingBox(); tm.computeBoundingBox();
    grp.add(hm, tm); heads.push(hm); tails.push(tm);
  }

  /* midplane seam */
  const seamMat = new THREE.LineBasicMaterial({ color: 0xC98F7C, clippingPlanes: clips, transparent: true, opacity: 0.85 });
  const seam = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(XMIN, 0, ZMIN), new THREE.Vector3(XMAX, 0, ZMIN),
    new THREE.Vector3(XMAX, 0, ZMAX), new THREE.Vector3(XMIN, 0, ZMAX)
  ]), seamMat);
  grp.add(seam);

  /* glycerol interfacial band (highlight only) */
  const bandMat = new THREE.MeshBasicMaterial({
    color: 0xE8A33D, transparent: true, opacity: 0.8,
    side: THREE.DoubleSide, clippingPlanes: clips, depthWrite: false
  });
  const bandGeo = new THREE.BoxGeometry(XMAX - XMIN, 0.10, ZMAX - ZMIN);
  const bands = [];
  for (const sgn of [1, -1]) {
    const b = new THREE.Mesh(bandGeo, bandMat);
    b.position.set((XMIN + XMAX) / 2, sgn * 1.0, 0);
    b.visible = false;
    grp.add(b); bands.push(b);
  }

  scene.add(grp);
  return { grp, matHead, matTail, bands, heads, tails };
}

const slabA = buildSlab([planeA]);
const slabB = buildSlab([planeB1, planeB2]);
const slabs = [slabA, slabB];

/* ── cut-face caps ──────────────────────────────────────────────────────── */
const capMat = new THREE.MeshStandardMaterial({ color: 0xE5BCA9, roughness: 0.92, side: THREE.DoubleSide });
const capSeamMat = new THREE.MeshBasicMaterial({ color: 0xC98F7C, side: THREE.DoubleSide });
function makeCap() {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), capMat);
  const s = new THREE.Mesh(new THREE.PlaneGeometry(1, 0.012), capSeamMat);
  s.position.set(0, 0, 0.003);
  m.add(s);
  scene.add(m);
  return m;
}
const capX = makeCap(); capX.rotation.y = Math.PI / 2;   // faces +X
const capZ = makeCap();                                   // faces +Z

let cutT = 0.35, cutTarget = 0.35;
function applyCut(t) {
  const xCut = XMAX - 2.6 * t;
  const zCut = ZMAX - 1.8 * t;
  planeA.constant = xCut;
  planeB1.constant = -xCut;
  planeB2.constant = zCut;
  const show = t > 0.006;
  capX.visible = capZ.visible = show;
  if (show) {
    capX.position.set(xCut - 0.005, 0, (zCut + ZMAX) / 2);
    capX.scale.set(ZMAX - zCut, 2.06, 1);
    capZ.position.set((xCut + XMAX) / 2, 0, zCut - 0.005);
    capZ.scale.set(XMAX - xCut, 2.06, 1);
  }
  const lab = document.getElementById('cutVal');
  if (lab) lab.textContent = t.toFixed(2);
}

/* ── formula panel (flat line art, billboarded) ─────────────────────────── */
const FX = 4.5;
const formula = new THREE.Group();
formula.position.set(FX, 0, 0);
scene.add(formula);

function SB() { this.v = []; }
SB.prototype.tri = function (a, b, c) {
  this.v.push(a[0] - FX, a[1], 0, b[0] - FX, b[1], 0, c[0] - FX, c[1], 0);
};
SB.prototype.quad = function (a, b, c, d) { this.tri(a, b, c); this.tri(a, c, d); };
SB.prototype.seg = function (x1, y1, x2, y2, w) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  const nx = -dy / L * w / 2, ny = dx / L * w / 2;
  this.quad([x1 + nx, y1 + ny], [x2 + nx, y2 + ny], [x2 - nx, y2 - ny], [x1 - nx, y1 - ny]);
};
SB.prototype.dbl = function (x, y, angDeg, r0, r1, gap, w) {
  const a = angDeg * Math.PI / 180, ux = Math.cos(a), uy = Math.sin(a), px = -uy, py = ux;
  for (const s of [-1, 1]) {
    this.seg(x + ux * r0 + px * gap * s, y + uy * r0 + py * gap * s,
      x + ux * r1 + px * gap * s, y + uy * r1 + py * gap * s, w);
  }
};
SB.prototype.arrow = function (x1, y1, x2, y2, w, hw, hl) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  const bx = x2 - ux * hl, by = y2 - uy * hl;
  this.seg(x1, y1, bx, by, w);
  this.tri([x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]);
};
SB.prototype.ribbon = function (x0, x1, y, amp, waves, w) {
  const N = 110; const pts = [];
  for (let i = 0; i <= N; i++) {
    const u = i / N, x = x0 + (x1 - x0) * u;
    const yy = y + Math.sin(u * Math.PI * 2 * waves + 0.5) * amp * (0.45 + 0.55 * Math.sin(u * Math.PI));
    pts.push([x, yy]);
  }
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const ww = w * (0.72 + 0.28 * Math.sin(u * Math.PI));
    this.seg(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], ww);
  }
};
SB.prototype.mesh = function (color, order) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(this.v, 3));
  g.computeBoundingSphere(); g.computeBoundingBox();
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
  }));
  m.renderOrder = order || 1;
  formula.add(m);
  return m;
};

const BW = 0.032;
/* black: glycerol backbone + ester links */
const kb = new SB();
kb.seg(1.20, 1.76, 1.20, 0.20, BW);
kb.seg(1.20, -0.20, 1.20, -1.76, BW);
kb.seg(1.50, 0.00, 2.26, 0.00, BW);
kb.seg(2.54, 0.00, 3.26, 0.00, BW);
kb.seg(1.62, -2.00, 2.26, -2.00, BW);
kb.seg(2.54, -2.00, 3.26, -2.00, BW);
kb.dbl(3.40, 0.00, 90, 0.22, 0.74, 0.07, BW);
kb.dbl(3.40, -2.00, 90, 0.22, 0.74, 0.07, BW);
const blackMesh = kb.mesh(0x1A1A1A, 2);

/* green: phosphocholine head */
const kg = new SB();
kg.seg(1.62, 2.00, 1.99, 2.00, BW);
kg.seg(2.27, 2.00, 2.86, 2.00, BW);
kg.seg(3.14, 2.00, 3.74, 2.00, BW);
kg.seg(4.02, 2.00, 4.48, 2.00, BW);
kg.dbl(3.00, 2.00, 120, 0.17, 0.60, 0.055, BW);      // P=O
kg.seg(3.00 + Math.cos(Math.PI / 3) * 0.17, 2.00 + Math.sin(Math.PI / 3) * 0.17,
  3.00 + Math.cos(Math.PI / 3) * 0.60, 2.00 + Math.sin(Math.PI / 3) * 0.60, BW); // P—O⁻
const greenMesh = kg.mesh(0x17A06A, 2);

const kga = new SB();
kga.arrow(5.75, 3.02, 4.40, 2.33, 0.030, 0.105, 0.26);
const greenArrow = kga.mesh(0x17A06A, 2);

/* tan fatty-acyl ribbons */
const kt = new SB();
kt.ribbon(3.62, 7.60, -0.08, 0.075, 4, 0.13);
kt.ribbon(3.62, 7.50, -2.08, 0.075, 4, 0.13);
const ribbonMesh = kt.mesh(0xD9A38E, 2);

/* magenta arrows */
const km = new SB();
km.arrow(8.05, -0.90, 7.70, -0.20, 0.030, 0.105, 0.24);
km.arrow(8.05, -1.32, 7.58, -1.98, 0.030, 0.105, 0.24);
const magentaArrow = km.mesh(0xE0218A, 2);

/* ── labels ─────────────────────────────────────────────────────────────── */
const labelRecs = [];
function fLabel(text, x, y, opts, region) {
  const local = new THREE.Vector3(x - FX, y, 0);
  const e = addLabel(text, local.clone().add(formula.position), opts);
  labelRecs.push({ entry: e, local, region });
  return e;
}
const CHEM = { fontSize: '42px', color: '#1A1A1A' };
const CHEMG = { fontSize: '42px', color: '#17A06A' };
const CALL = { fontSize: '48px', bold: true };

/* glycerol backbone + esters (black) */
fLabel('CH<sub>2</sub>', 1.20, 2.00, CHEM, 'glycerol');
fLabel('CH', 1.20, 0.00, CHEM, 'glycerol');
fLabel('CH<sub>2</sub>', 1.20, -2.00, CHEM, 'glycerol');
fLabel('O', 2.40, 0.00, CHEM, 'glycerol');
fLabel('C', 3.40, 0.00, CHEM, 'glycerol');
fLabel('O', 3.40, 0.98, CHEM, 'glycerol');
fLabel('O', 2.40, -2.00, CHEM, 'glycerol');
fLabel('C', 3.40, -2.00, CHEM, 'glycerol');
fLabel('O', 3.40, -1.02, CHEM, 'glycerol');

/* ionic head (green) */
fLabel('O', 2.15, 2.00, CHEMG, 'head');
fLabel('P', 3.00, 2.00, CHEMG, 'head');
fLabel('O', 3.90, 2.00, CHEMG, 'head');
fLabel('O', 2.62, 2.78, CHEMG, 'head');
fLabel('O<sup>&minus;</sup>', 3.44, 2.80, CHEMG, 'head');
fLabel('CH<sub>2</sub>CH<sub>2</sub>N(CH<sub>3</sub>)<sub>3</sub><sup>+</sup>', 5.65, 2.00, CHEMG, 'head');
fLabel('Ionic head', 6.30, 3.32, { ...CALL, color: '#17A06A' }, 'head');

/* tails (magenta callout) */
fLabel('Nonpolar tails', 9.50, -1.12, { ...CALL, color: '#E0218A' }, 'tails');

/* ── glow overlays / click targets ──────────────────────────────────────── */
const glowPlanes = {};
function glow(region, cx, cy, w, h, color, info) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide
  }));
  m.position.set(cx - FX, cy, -0.06);
  m.renderOrder = 0;
  formula.add(m);
  registerInteractive(m, { ...info, onClick: () => setHighlight(region) });
  glowPlanes[region] = m;
  return m;
}
glow('head', 4.60, 2.42, 5.40, 1.70, 0x17A06A, {
  title: 'Ionic head (phosphocholine)',
  tooltip: 'Ionic head — click to light the slab surfaces',
  body: 'The phosphate–choline group carries a negative and a positive charge. It is strongly attracted to water, so in the assembled bilayer it forms the green bead layers that pave BOTH outer faces of the membrane.'
});
glow('glycerol', 2.30, -0.05, 3.40, 4.90, 0xE8A33D, {
  title: 'Glycerol backbone and ester links',
  tooltip: 'Glycerol linker — click to light the interfacial band',
  body: 'The three-carbon glycerol backbone (CH2–CH–CH2) and its two ester carbonyls join the polar head to the nonpolar tails. In the slab it occupies only a narrow band right where green meets tan.'
});
glow('tails', 5.60, -1.08, 4.60, 3.10, 0xE0218A, {
  title: 'Nonpolar tails',
  tooltip: 'Nonpolar tails — click to light the membrane core',
  body: 'Two long hydrocarbon chains, drawn as tan ribbons. They avoid water, so they point inward and interdigitate tip-to-tip at the midplane, filling the entire interior of the bilayer.'
});

/* slab click targets */
for (const s of slabs) {
  s.heads.forEach(h => registerInteractive(h, {
    title: 'Head-group layer', tooltip: 'Polar heads — water-facing surface',
    body: 'Each green bead is one phosphocholine head group. They tile both outer faces of the bilayer, the only part of the lipid that contacts water.',
    onClick: () => setHighlight('head')
  }));
  s.tails.forEach(t => registerInteractive(t, {
    title: 'Hydrocarbon core', tooltip: 'Nonpolar tails — membrane interior',
    body: 'The tan strands are the fatty-acyl tails. Tails of the two leaflets meet tip-to-tip at the midplane, so hydrocarbon is completely sealed away from water.',
    onClick: () => setHighlight('tails')
  }));
}

/* ── highlight logic ────────────────────────────────────────────────────── */
const regionMeshes = {
  head: [greenMesh, greenArrow],
  glycerol: [blackMesh],
  tails: [ribbonMesh, magentaArrow]
};
const GLOWCSS = { head: 'rgba(23,160,106,0.9)', glycerol: 'rgba(232,163,61,0.95)', tails: 'rgba(224,33,138,0.85)' };
let hl = 'none';
function setHighlight(h) {
  hl = h;
  for (const r of ['head', 'glycerol', 'tails']) {
    const on = (h === r), dim = (h !== 'none' && !on);
    regionMeshes[r].forEach(m => { m.material.opacity = dim ? 0.20 : 1; });
    glowPlanes[r].material.opacity = on ? 0.18 : 0;
  }
  for (const rec of labelRecs) {
    const on = (hl === rec.region), dim = (hl !== 'none' && !on);
    rec.entry.div.style.opacity = dim ? 0.22 : 1;
    rec.entry.div.style.textShadow = on ? `0 0 7px ${GLOWCSS[rec.region]}` : 'none';
  }
  for (const s of slabs) {
    s.matHead.color.set((h === 'none' || h === 'head') ? 0xffffff : 0x9aa09c);
    s.matHead.emissive.set(h === 'head' ? 0x17A06A : 0x000000);
    s.matTail.color.set((h === 'none' || h === 'tails') ? 0xffffff : 0xa8a29d);
    s.matTail.emissive.set(h === 'tails' ? 0x7a1040 : 0x000000);
    s.bands.forEach(b => { b.visible = (h === 'glycerol'); });
  }
  document.querySelectorAll('#partBtns button').forEach(b =>
    b.classList.toggle('active', b.dataset.part === h));
}

/* ── camera (after geometry) ───────────────────────────────────────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 40, elevationDeg: 25, rollDeg: 0, heightFraction: 0.6 };
applyCut(cutT);
setCameraView(VIEW);
formula.quaternion.copy(camera.quaternion);
setCameraView(VIEW);
setHighlight('none');

/* ── billboard + tween loop ────────────────────────────────────────────── */
const _wq = new THREE.Quaternion();
function updateBillboard() {
  formula.quaternion.copy(camera.quaternion);
  _wq.copy(camera.quaternion);
  for (const rec of labelRecs) {
    rec.entry.pos.copy(rec.local).applyQuaternion(_wq).add(formula.position);
  }
}
let _last = performance.now(), _playT = 0, playing = false;
(function loop() {
  requestAnimationFrame(loop);
  const now = performance.now(), dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (Math.abs(cutTarget - cutT) > 0.001) {
    cutT += (cutTarget - cutT) * Math.min(1, dt * 5.5);
    applyCut(cutT);
    const sl = document.getElementById('cutaway'); if (sl) sl.value = cutT.toFixed(2);
  }
  if (playing) {
    _playT += dt;
    if (_playT > 5.0) { _playT = 0; goToStep(stepIdx + 1); }
  }
  updateBillboard();
})();

/* ── controls ──────────────────────────────────────────────────────────── */
document.querySelectorAll('#partBtns button').forEach(b => {
  b.addEventListener('click', () => setHighlight(b.dataset.part));
});
const slider = document.getElementById('cutaway');
slider.addEventListener('input', () => {
  cutT = cutTarget = parseFloat(slider.value);
  applyCut(cutT);
});

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Intact membrane', cut: 0, part: 'none',
    narr: 'A slab of bilayer sits beside the glycerophospholipid that builds it. Only green head groups are visible from outside; the whole hydrocarbon interior is buried.'
  },
  {
    title: 'Ionic head at the surface', cut: 0, part: 'head',
    narr: 'Highlighting the phosphocholine group turns the green spheres on both faces of the slab: the charged head is what contacts water, on both sides of the membrane.'
  },
  {
    title: 'Cut into the core', cut: 0.55, part: 'tails',
    narr: 'Opening the corner cutaway reveals the tan tails packed between the two head layers, and the seam at mid-thickness where tail tips from opposing leaflets meet.'
  },
  {
    title: 'Glycerol at the boundary', cut: 0.70, part: 'glycerol',
    narr: 'The glycerol backbone and its two ester carbonyls sit exactly where green meets tan — the narrow interfacial band that joins the polar surface to the nonpolar interior.'
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setHighlight(s.part);
  cutTarget = s.cut;
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNext').addEventListener('click', () => { _playT = 0; goToStep(stepIdx + 1); });
document.getElementById('btnPrev').addEventListener('click', () => { _playT = 0; goToStep(stepIdx - 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing; _playT = 0;
  e.target.textContent = playing ? '❚❚ Pause' : '▶ Play';
  if (playing && stepIdx < 0) goToStep(0);
});
document.getElementById('stepTitle').textContent = 'Press Play or Next ▶';
document.getElementById('stepNarr').textContent = 'Four steps map each region of the drawn molecule onto its layer in the assembled bilayer.';
// @FIGURE_CODE_END

