// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 // head beads (2 leaflets)   → InstancedMesh SphereGeometry(0.13,9,6), Phong glossy, #5CCF9A→#A9E9C9
 // hydrocarbon tails         → InstancedMesh TubeGeometry(gentle 2-bend CatmullRom, r=0.036), #D9A38E→#E7C0AE
 // interior core (L-shaped)  → 2× BoxGeometry, pale tan #E3B7A4 (inset so tails stand proud on cut walls)
 // midplane seam             → 2× thin BoxGeometry at y=0, #C98F7C
 // glycerol band (highlight) → 4× thin BoxGeometry at y=±0.79, amber #E8A33D (hidden by default)
 // stepped corner cutaway    → per-instance scale-to-zero over the notch footprint (x>xCut && z>zCut)
 // formula bonds (black)     → merged quad BufferGeometry #1A1A1A
 // formula bonds (green)     → merged quad BufferGeometry #17A06A (+ P=O, O⁻, long arrow)
 // fatty-acyl ribbons        → merged low-frequency wavy quad strip #D9A38E
 // magenta arrows            → merged quad+triangle BufferGeometry #E0218A
 // glow overlays             → PlaneGeometry per region, transparent, also click targets
 // all text                  → addLabel (HTML sub/superscripts), auto-sized in screen pixels
──────────────────────────────────────────────────────────────────────────── */

document.getElementById('btnReset').style.display = '';

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.46));
scene.add(new THREE.HemisphereLight(0xffffff, 0xd8e2dc, 0.48));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-6, 9, 7); scene.add(keyLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.40);
rimLight.position.set(7, 5, 6); scene.add(rimLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.16);
fillLight.position.set(4, -6, -6); scene.add(fillLight);

/* ── slab geometry (wide & thin, matching the source proportions) ───────── */
const SP = 0.30, NX = 26, NZ = 13, HR = 0.13, HY = 0.85, TL = 0.80, CX = -5.6;
const XMIN = CX - (NX - 1) / 2 * SP - HR;
const XMAX = CX + (NX - 1) / 2 * SP + SP / 2 + HR;
const ZMIN = -(NZ - 1) / 2 * SP - HR;
const ZMAX = (NZ - 1) / 2 * SP + HR;

const headGeo = new THREE.SphereGeometry(HR, 9, 6);
const tailPts = [];
for (let i = 0; i <= 6; i++) {
  const u = i / 6;
  tailPts.push(new THREE.Vector3(
    Math.sin(u * Math.PI * 1.8) * 0.07,
    -u * TL,
    Math.sin(u * Math.PI * 1.25) * 0.03
  ));
}
const tailGeo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(tailPts), 10, 0.036, 5, false);

const matHead = new THREE.MeshPhongMaterial({
  color: 0xffffff, specular: 0xffffff, shininess: 80, emissive: 0x000000
});
const matTail = new THREE.MeshPhongMaterial({
  color: 0xffffff, specular: 0x6b5147, shininess: 14, emissive: 0x000000
});

const slabGroup = new THREE.Group();
scene.add(slabGroup);

const basePos = [];                       // {x,z} per instance index
for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++) {
  basePos.push({
    x: CX + (i - (NX - 1) / 2) * SP + (j % 2 ? SP / 2 : 0),
    z: (j - (NZ - 1) / 2) * SP
  });
}
const NINST = basePos.length;

const instSets = [];                      // {mesh, on:[Matrix4], off:[Matrix4]}
const headMeshes = [], tailMeshes = [];
{
  const o = new THREE.Object3D();
  const cA = new THREE.Color(), cB = new THREE.Color();
  for (const sgn of [1, -1]) {
    const hm = new THREE.InstancedMesh(headGeo, matHead, NINST);
    const tm = new THREE.InstancedMesh(tailGeo, matTail, NINST);
    const hOn = [], hOff = [], tOn = [], tOff = [];
    for (let k = 0; k < NINST; k++) {
      const { x, z } = basePos[k];
      const y = sgn * HY;
      const r = ((k * 2654435761) % 1000) / 1000;

      o.position.set(x, y, z);
      o.rotation.set(0, r * 6.283, 0);
      o.scale.setScalar(0.93 + r * 0.13);
      o.updateMatrix(); hm.setMatrixAt(k, o.matrix); hOn.push(o.matrix.clone());
      o.scale.setScalar(0.0001); o.updateMatrix(); hOff.push(o.matrix.clone());
      hm.setColorAt(k, cA.set(0x5CCF9A).lerp(cB.set(0xA9E9C9), 0.20 + 0.80 * r));

      o.position.set(x, y, z);
      o.rotation.set(sgn > 0 ? 0 : Math.PI, r * 6.283, 0);
      o.scale.setScalar(1);
      o.updateMatrix(); tm.setMatrixAt(k, o.matrix); tOn.push(o.matrix.clone());
      o.scale.setScalar(0.0001); o.updateMatrix(); tOff.push(o.matrix.clone());
      tm.setColorAt(k, cA.set(0xD9A38E).lerp(cB.set(0xE7C0AE), r));
    }
    hm.instanceMatrix.needsUpdate = true; hm.instanceColor.needsUpdate = true;
    tm.instanceMatrix.needsUpdate = true; tm.instanceColor.needsUpdate = true;
    hm.frustumCulled = false; tm.frustumCulled = false;
    slabGroup.add(hm, tm);
    headMeshes.push(hm); tailMeshes.push(tm);
    instSets.push({ mesh: hm, on: hOn, off: hOff }, { mesh: tm, on: tOn, off: tOff });
  }
}

/* ── interior core / seam / glycerol bands (L-shaped, follow the notch) ─── */
const unitBox = new THREE.BoxGeometry(1, 1, 1);
const coreMat = new THREE.MeshPhongMaterial({ color: 0xE3B7A4, specular: 0x3a2b26, shininess: 6 });
const seamMat = new THREE.MeshBasicMaterial({ color: 0xC98F7C });
const bandMat = new THREE.MeshBasicMaterial({ color: 0xE8A33D, transparent: true, opacity: 0.9 });

function mkBox(mat) { const m = new THREE.Mesh(unitBox, mat); slabGroup.add(m); return m; }
const coreA = mkBox(coreMat), coreB = mkBox(coreMat);
const seamA = mkBox(seamMat), seamB = mkBox(seamMat);
const bandA = [mkBox(bandMat), mkBox(bandMat)], bandB = [mkBox(bandMat), mkBox(bandMat)];
const bands = [...bandA, ...bandB];
bands.forEach(b => b.visible = false);

function setBox(m, x0, x1, z0, z1, yc, yh) {
  const w = Math.max(0.001, x1 - x0), dd = Math.max(0.001, z1 - z0);
  m.position.set((x0 + x1) / 2, yc, (z0 + z1) / 2);
  m.scale.set(w, yh, dd);
}

const IN = 0.09;
let cutT = 0.35, cutTarget = 0.35;

function applyCut(t) {
  const xCut = XMAX - 2.7 * t;
  const zCut = ZMAX - 1.9 * t;

  for (const set of instSets) {
    for (let k = 0; k < NINST; k++) {
      const b = basePos[k];
      const gone = (b.x > xCut && b.z > zCut);
      set.mesh.setMatrixAt(k, gone ? set.off[k] : set.on[k]);
    }
    set.mesh.instanceMatrix.needsUpdate = true;
  }

  setBox(coreA, XMIN + IN, xCut - IN, ZMIN + IN, ZMAX - IN, 0, 2 * HY);
  setBox(seamA, XMIN + IN - 0.015, xCut - IN + 0.015, ZMIN + IN - 0.015, ZMAX - IN + 0.015, 0, 0.03);
  bandA.forEach((b, i) => setBox(b, XMIN + IN - 0.01, xCut - IN + 0.01,
    ZMIN + IN - 0.01, ZMAX - IN + 0.01, (i ? -1 : 1) * (HY - 0.05), 0.07));

  const showB = t > 0.012 && (zCut - IN) > (ZMIN + IN);
  coreB.visible = seamB.visible = showB;
  if (showB) {
    setBox(coreB, xCut - IN - 0.03, XMAX - IN, ZMIN + IN, zCut - IN, 0, 2 * HY);
    setBox(seamB, xCut - IN - 0.03, XMAX - IN + 0.015, ZMIN + IN - 0.015, zCut - IN + 0.015, 0, 0.03);
    bandB.forEach((b, i) => setBox(b, xCut - IN - 0.03, XMAX - IN + 0.01,
      ZMIN + IN - 0.01, zCut - IN + 0.01, (i ? -1 : 1) * (HY - 0.05), 0.07));
  }
  bandB.forEach(b => { if (!showB) b.visible = false; else b.visible = (hl === 'glycerol'); });

  const lab = document.getElementById('cutVal');
  if (lab) lab.textContent = t.toFixed(2);
}

/* ── formula panel (flat line art, billboarded, well clear of the slab) ─── */
const FX = 4.5;
const formula = new THREE.Group();
formula.position.set(8.2, 0.15, 0);
scene.add(formula);

function SB() { this.v = []; }
SB.prototype.tri = function (a, b, c) {
  this.v.push(a[0] - FX, a[1], 0, b[0] - FX, b[1], 0, c[0] - FX, c[1], 0);
};
SB.prototype.quad = function (a, b, c, d) { this.tri(a, b, c); this.tri(a, c, d); };
SB.prototype.seg = function (x1, y1, x2, y2, w) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  const nx = -dy / L * w / 2, ny = dx / L * w / 2;
  this.quad([x1 + nx, y1 + ny], [x2 + nx, y2 + ny], [x2 - nx, y2 - ny], [x1 - nx, y1 - ny]);
};
SB.prototype.dbl = function (x, y, angDeg, r0, r1, gap, w) {
  const a = angDeg * Math.PI / 180, ux = Math.cos(a), uy = Math.sin(a), px = -uy, py = ux;
  for (const s of [-1, 1]) {
    this.seg(x + ux * r0 + px * gap * s, y + uy * r0 + py * gap * s,
      x + ux * r1 + px * gap * s, y + uy * r1 + py * gap * s, w);
  }
};
SB.prototype.arrow = function (x1, y1, x2, y2, w, hw, hl2) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  const bx = x2 - ux * hl2, by = y2 - uy * hl2;
  this.seg(x1, y1, bx, by, w);
  this.tri([x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]);
};
SB.prototype.ribbon = function (x0, x1, y, amp, waves, w) {
  const N = 90, pts = [];
  for (let i = 0; i <= N; i++) {
    const u = i / N, x = x0 + (x1 - x0) * u;
    const yy = y + Math.sin(u * Math.PI * 2 * waves + 0.4) * amp * (0.55 + 0.45 * Math.sin(u * Math.PI));
    pts.push([x, yy]);
  }
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const ww = w * (0.78 + 0.22 * Math.sin(u * Math.PI));
    this.seg(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], ww);
  }
};
SB.prototype.mesh = function (color, order) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(this.v, 3));
  g.computeBoundingSphere(); g.computeBoundingBox();
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
  }));
  m.renderOrder = order || 1;
  formula.add(m);
  return m;
};

const BW = 0.032;
/* black: glycerol backbone + ester links */
const kb = new SB();
kb.seg(1.20, 1.74, 1.20, 0.22, BW);
kb.seg(1.20, -0.22, 1.20, -1.74, BW);
kb.seg(1.48, 0.00, 2.24, 0.00, BW);
kb.seg(2.56, 0.00, 3.24, 0.00, BW);
kb.seg(1.60, -2.00, 2.24, -2.00, BW);
kb.seg(2.56, -2.00, 3.24, -2.00, BW);
kb.dbl(3.40, 0.00, 90, 0.24, 0.74, 0.07, BW);
kb.dbl(3.40, -2.00, 90, 0.24, 0.74, 0.07, BW);
const blackMesh = kb.mesh(0x1A1A1A, 2);

/* green: phosphocholine head */
const kg = new SB();
kg.seg(1.62, 2.00, 1.97, 2.00, BW);
kg.seg(2.31, 2.00, 2.84, 2.00, BW);
kg.seg(3.16, 2.00, 3.72, 2.00, BW);
kg.seg(4.06, 2.00, 4.48, 2.00, BW);
kg.dbl(3.00, 2.00, 120, 0.18, 0.62, 0.055, BW);                       // P=O
kg.seg(3.00 + Math.cos(Math.PI / 3) * 0.18, 2.00 + Math.sin(Math.PI / 3) * 0.18,
  3.00 + Math.cos(Math.PI / 3) * 0.62, 2.00 + Math.sin(Math.PI / 3) * 0.62, BW);  // P—O⁻
const greenMesh = kg.mesh(0x17A06A, 2);

const kga = new SB();
kga.arrow(6.02, 3.10, 4.02, 2.30, 0.032, 0.115, 0.30);                // longer callout arrow
const greenArrow = kga.mesh(0x17A06A, 2);

/* tan fatty-acyl ribbons — low wave frequency, smooth undulation */
const kt = new SB();
kt.ribbon(3.66, 7.62, -0.08, 0.062, 2.4, 0.14);
kt.ribbon(3.66, 7.52, -2.08, 0.062, 2.4, 0.14);
const ribbonMesh = kt.mesh(0xD9A38E, 2);

/* magenta arrows */
const km = new SB();
km.arrow(8.40, -0.86, 7.70, -0.16, 0.032, 0.115, 0.28);
km.arrow(8.40, -1.38, 7.58, -2.00, 0.032, 0.115, 0.28);
const magentaArrow = km.mesh(0xE0218A, 2);

/* ── labels ─────────────────────────────────────────────────────────────── */
const labelRecs = [];
function fLabel(text, x, y, px, opts, region) {
  const local = new THREE.Vector3(x - FX, y, 0);
  const e = addLabel(text, local.clone().add(formula.position), opts);
  labelRecs.push({ entry: e, local, region, px });
  return e;
}
const CHEM = { color: '#1A1A1A' };
const CHEMG = { color: '#17A06A' };

/* glycerol backbone + esters (black) */
fLabel('CH<sub>2</sub>', 1.20, 2.00, 13, CHEM, 'glycerol');
fLabel('CH', 1.20, 0.00, 13, CHEM, 'glycerol');
fLabel('CH<sub>2</sub>', 1.20, -2.00, 13, CHEM, 'glycerol');
fLabel('O', 2.40, 0.00, 13, CHEM, 'glycerol');
fLabel('C', 3.40, 0.00, 13, CHEM, 'glycerol');
fLabel('O', 3.40, 0.98, 13, CHEM, 'glycerol');
fLabel('O', 2.40, -2.00, 13, CHEM, 'glycerol');
fLabel('C', 3.40, -2.00, 13, CHEM, 'glycerol');
fLabel('O', 3.40, -1.02, 13, CHEM, 'glycerol');

/* ionic head (green) */
fLabel('O', 2.14, 2.00, 13, CHEMG, 'head');
fLabel('P', 3.00, 2.00, 13, CHEMG, 'head');
fLabel('O', 3.89, 2.00, 13, CHEMG, 'head');
fLabel('O', 2.62, 2.80, 13, CHEMG, 'head');
fLabel('O<sup>&minus;</sup>', 3.44, 2.82, 13, CHEMG, 'head');
fLabel('CH<sub>2</sub>CH<sub>2</sub>N(CH<sub>3</sub>)<sub>3</sub><sup>+</sup>', 5.70, 2.00, 13, CHEMG, 'head');

/* callouts — deliberately larger than the atom labels */
fLabel('Ionic head', 6.95, 3.32, 20, { color: '#17A06A', bold: true }, 'head');
fLabel('Nonpolar tails', 9.80, -1.10, 20, { color: '#E0218A', bold: true }, 'tails');

/* ── glow overlays / click targets ──────────────────────────────────────── */
const glowPlanes = {};
function glow(region, cx, cy, w, h, color, info) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide
  }));
  m.position.set(cx - FX, cy, -0.06);
  m.renderOrder = 0;
  formula.add(m);
  registerInteractive(m, { ...info, onClick: () => setHighlight(region) });
  glowPlanes[region] = m;
  return m;
}
glow('head', 4.65, 2.44, 5.60, 1.80, 0x17A06A, {
  title: 'Ionic head (phosphocholine)',
  tooltip: 'Ionic head — click to light the slab surfaces',
  body: 'The phosphate–choline group carries a negative and a positive charge. It is strongly attracted to water, so in the assembled bilayer it forms the green bead layers that pave BOTH outer faces of the membrane.'
});
glow('glycerol', 2.30, -0.05, 3.40, 4.90, 0xE8A33D, {
  title: 'Glycerol backbone and ester links',
  tooltip: 'Glycerol linker — click to light the interfacial band',
  body: 'The three-carbon glycerol backbone (CH2–CH–CH2) and its two ester carbonyls join the polar head to the nonpolar tails. In the slab it occupies only a narrow band right where green meets tan.'
});
glow('tails', 5.60, -1.08, 4.60, 3.10, 0xE0218A, {
  title: 'Nonpolar tails',
  tooltip: 'Nonpolar tails — click to light the membrane core',
  body: 'Two long hydrocarbon chains, drawn as tan ribbons. They avoid water, so they point inward and interdigitate tip-to-tip at the midplane, filling the entire interior of the bilayer.'
});

/* slab click targets */
headMeshes.forEach(h => registerInteractive(h, {
  title: 'Head-group layer', tooltip: 'Polar heads — water-facing surface',
  body: 'Each green bead is one phosphocholine head group. They tile both outer faces of the bilayer, the only part of the lipid that contacts water.',
  onClick: () => setHighlight('head')
}));
tailMeshes.forEach(t => registerInteractive(t, {
  title: 'Hydrocarbon core', tooltip: 'Nonpolar tails — membrane interior',
  body: 'The tan strands are the fatty-acyl tails. Tails of the two leaflets meet tip-to-tip at the midplane, so hydrocarbon is completely sealed away from water.',
  onClick: () => setHighlight('tails')
}));
registerInteractive(coreA, {
  title: 'Hydrocarbon core', tooltip: 'Membrane interior',
  body: 'The pale tan body between the two bead layers is solid hydrocarbon — the tails of both leaflets packed together.',
  onClick: () => setHighlight('tails')
});

/* ── highlight logic ────────────────────────────────────────────────────── */
const regionMeshes = {
  head: [greenMesh, greenArrow],
  glycerol: [blackMesh],
  tails: [ribbonMesh, magentaArrow]
};
const GLOWCSS = { head: 'rgba(23,160,106,0.9)', glycerol: 'rgba(232,163,61,0.95)', tails: 'rgba(224,33,138,0.85)' };
let hl = 'none';
function setHighlight(h) {
  hl = h;
  for (const r of ['head', 'glycerol', 'tails']) {
    const on = (h === r), dim = (h !== 'none' && !on);
    regionMeshes[r].forEach(m => { m.material.opacity = dim ? 0.20 : 1; });
    glowPlanes[r].material.opacity = on ? 0.18 : 0;
  }
  for (const rec of labelRecs) {
    const on = (hl === rec.region), dim = (hl !== 'none' && !on);
    rec.entry.div.style.opacity = dim ? 0.22 : 1;
    rec.entry.div.style.textShadow = on ? `0 0 8px ${GLOWCSS[rec.region]}` : 'none';
  }
  matHead.color.set((h === 'none' || h === 'head') ? 0xffffff : 0x9aa09c);
  matHead.emissive.set(h === 'head' ? 0x1d7f57 : 0x000000);
  matTail.color.set((h === 'none' || h === 'tails') ? 0xffffff : 0xa8a29d);
  matTail.emissive.set(h === 'tails' ? 0x6d1338 : 0x000000);
  coreMat.color.set((h === 'none' || h === 'tails') ? 0xE3B7A4 : 0xB9B2AC);
  coreMat.emissive.set(h === 'tails' ? 0x4d0d27 : 0x000000);
  bandA.forEach(b => b.visible = (h === 'glycerol'));
  bandB.forEach(b => b.visible = (h === 'glycerol') && coreB.visible);
  document.querySelectorAll('#partBtns button').forEach(b =>
    b.classList.toggle('active', b.dataset.part === h));
}

/* ── camera (after all geometry) ───────────────────────────────────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 40, elevationDeg: 25, rollDeg: 0, heightFraction: 0.66 };
applyCut(cutT);
setCameraView(VIEW);
formula.quaternion.copy(camera.quaternion);
setCameraView(VIEW);
setHighlight('none');

/* size labels so their on-screen pixel size matches the source hierarchy */
(function sizeLabels() {
  const dist = camera.position.distanceTo(formula.position);
  const s = Math.max(0.05, 8 / dist);
  for (const rec of labelRecs) rec.entry.div.style.fontSize = (rec.px / s).toFixed(1) + 'px';
})();

/* ── billboard + tween loop ────────────────────────────────────────────── */
const _wq = new THREE.Quaternion();
function updateBillboard() {
  formula.quaternion.copy(camera.quaternion);
  _wq.copy(camera.quaternion);
  for (const rec of labelRecs) {
    rec.entry.pos.copy(rec.local).applyQuaternion(_wq).add(formula.position);
  }
}
let _last = performance.now(), _playT = 0, playing = false;
(function loop() {
  requestAnimationFrame(loop);
  try {
    const now = performance.now(), dt = Math.min(0.05, (now - _last) / 1000); _last = now;
    if (Math.abs(cutTarget - cutT) > 0.002) {
      cutT += (cutTarget - cutT) * Math.min(1, dt * 5.0);
      applyCut(cutT);
      bandB.forEach(b => b.visible = (hl === 'glycerol') && coreB.visible);
      const sl = document.getElementById('cutaway'); if (sl) sl.value = cutT.toFixed(2);
    }
    if (playing) {
      _playT += dt;
      if (_playT > 5.5) { _playT = 0; goToStep(stepIdx + 1); }
    }
    updateBillboard();
  } catch (e) { /* never stall the figure */ }
})();

/* ── controls ──────────────────────────────────────────────────────────── */
document.querySelectorAll('#partBtns button').forEach(b => {
  b.addEventListener('click', () => setHighlight(b.dataset.part));
});
const slider = document.getElementById('cutaway');
slider.addEventListener('input', () => {
  cutT = cutTarget = parseFloat(slider.value);
  applyCut(cutT);
  bandB.forEach(b => b.visible = (hl === 'glycerol') && coreB.visible);
});

/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
