})();

/* ── controls ──────────────────────────────────────────────────────────── */
document.querySelectorAll('#partBtns button').forEach(b => {
  b.addEventListener('click', () => setHighlight(b.dataset.part));
});
const slider = document.getElementById('cutaway');
slider.addEventListener('input', () => {
  cutT = cutTarget = parseFloat(slider.value);
