/* ── guided tour ───────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Intact membrane', cut: 0, part: 'none',
    narr: 'A slab of bilayer sits beside the glycerophospholipid that builds it. Only green head groups are visible from outside; the whole hydrocarbon interior is buried.'
  },
  {
    title: 'Ionic head at the surface', cut: 0, part: 'head',
    narr: 'Highlighting the phosphocholine group turns the green spheres on both faces of the slab: the charged head is what contacts water, on both sides of the membrane.'
  },
  {
    title: 'Cut into the core', cut: 0.55, part: 'tails',
    narr: 'Opening the stepped corner cutaway reveals the tan tails packed between the two head layers, and the seam at mid-thickness where tail tips from opposing leaflets meet.'
  },
  {
    title: 'Glycerol at the boundary', cut: 0.70, part: 'glycerol',
    narr: 'The glycerol backbone and its two ester carbonyls sit exactly where green meets tan — the narrow interfacial band that joins the polar surface to the nonpolar interior.'
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = ((i % STEPS.length) + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setHighlight(s.part);
  cutTarget = s.cut;
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('btnNext').addEventListener('click', () => { _playT = 0; goToStep(stepIdx + 1); });
document.getElementById('btnPrev').addEventListener('click', () => { _playT = 0; goToStep(stepIdx - 1); });
document.getElementById('btnPlay').addEventListener('click', (e) => {
  playing = !playing; _playT = 0;
  e.target.textContent = playing ? '❚❚ Pause' : '▶ Play';
  if (playing && stepIdx < 0) goToStep(0);
});
document.getElementById('stepTitle').textContent = 'Press Play or Next ▶';
document.getElementById('stepNarr').textContent = 'Four steps map each region of the drawn molecule onto its layer in the assembled bilayer.';
// @FIGURE_CODE_END

