// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
 // head beads (2 leaflets)   → InstancedMesh SphereGeometry(0.15,12,8) Phong glossy, #4FBF8F→#8FD9B6
 // hydrocarbon tails (2/head)→ 4× InstancedMesh TubeGeometry(kinked CatmullRom, r=0.055), #D9A38E→#EFD0C0
 // interior core (L-shaped)  → 2× BoxGeometry darker tan #C08D7B, inset 0.30 so tubes stand proud on cut walls
 // midplane seam             → 2× thin BoxGeometry at y=0, #AE7A69
 // glycerol bands            → 4× thin BoxGeometry at |y|=0.99, amber #E8A33D (hidden by default)
 // stepped corner cutaway    → per-instance scale-to-zero over notch footprint + L-shaped core boxes
 // hit proxies               → 2× opacity-0 BoxGeometry over the head layers (cheap picking)
 // formula bonds (black)     → merged quad BufferGeometry #1A1A1A
 // formula bonds (green)     → merged quad BufferGeometry #17A06A (+ P=O, O⁻, callout arrow)
 // fatty-acyl ribbons        → merged irregular wavy quad strip #D9A38E (3-octave kinks)
 // magenta arrows            → merged quad+triangle BufferGeometry #E0218A
 // glow overlays             → PlaneGeometry per region, transparent, also click targets
 // all text                  → addLabel (HTML sub/superscripts), sized in screen pixels
──────────────────────────────────────────────────────────────────────────── */

document.getElementById('btnReset').style.display = '';

let hl = 'none';

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.40));
scene.add(new THREE.HemisphereLight(0xffffff, 0xd8e2dc, 0.44));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.92);
keyLight.position.set(-6, 9, 7); scene.add(keyLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.38);
rimLight.position.set(7, 5, 6); scene.add(rimLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.15);
fillLight.position.set(4, -6, -6); scene.add(fillLight);

/* ── slab (7.2 × 2.5 × 4.5 world units, built centred on the origin) ────── */
const SP = 0.30, NX = 24, NZ = 15, HR = 0.15, HY = 1.10, TL = 1.05;
const XG1 = (NX - 1) / 2 * SP + SP / 4 + HR, XG0 = -XG1;
const ZG1 = (NZ - 1) / 2 * SP + HR, ZG0 = -ZG1;
const CYH = 0.96, IN = 0.30;

const rnd = (n) => { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); };

const headGeo = new THREE.SphereGeometry(HR, 12, 8);
const tailPts = [];
for (let i = 0; i <= 8; i++) {
  const u = i / 8;
  tailPts.push(new THREE.Vector3(
    Math.sin(u * Math.PI * 2.4 + 0.5) * 0.085 * (0.35 + 0.65 * u),
    -u * TL,
    Math.cos(u * Math.PI * 1.7) * 0.055 * u
  ));
}
const tailGeo = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(tailPts), 12, 0.055, 6, false);

const matHead = new THREE.MeshPhongMaterial({ color: 0xffffff, specular: 0xffffff, shininess: 95, emissive: 0x000000 });
const matTail = new THREE.MeshPhongMaterial({ color: 0xffffff, specular: 0x6b5147, shininess: 22, emissive: 0x000000 });

const slabGroup = new THREE.Group();
scene.add(slabGroup);

const basePos = [];
for (let j = 0; j < NZ; j++) for (let i = 0; i < NX; i++) {
  basePos.push({
    x: (i - (NX - 1) / 2) * SP + ((j % 2) ? SP / 4 : -SP / 4),
    z: (j - (NZ - 1) / 2) * SP
  });
}
const NINST = basePos.length;

const instSets = [];
{
  const o = new THREE.Object3D();
  const cA = new THREE.Color(), cB = new THREE.Color();
  for (const sgn of [1, -1]) {
    /* head beads */
    const hm = new THREE.InstancedMesh(headGeo, matHead, NINST);
    const hOn = [], hOff = [];
    for (let k = 0; k < NINST; k++) {
      const { x, z } = basePos[k];
      const r = rnd(k + (sgn > 0 ? 0.13 : 7.71));
      o.position.set(x, sgn * HY, z);
      o.rotation.set(0, r * 6.283, 0);
      o.scale.setScalar(0.93 + r * 0.15);
      o.updateMatrix(); hm.setMatrixAt(k, o.matrix); hOn.push(o.matrix.clone());
      o.scale.setScalar(0.0001); o.updateMatrix(); hOff.push(o.matrix.clone());
      hm.setColorAt(k, cA.set(0x4FBF8F).lerp(cB.set(0x8FD9B6), 0.15 + 0.85 * r));
    }
    hm.instanceMatrix.needsUpdate = true; hm.instanceColor.needsUpdate = true;
    hm.frustumCulled = false;
    slabGroup.add(hm);
    instSets.push({ mesh: hm, on: hOn, off: hOff, base: basePos });

    /* two hydrocarbon chains per head */
    for (const c of [0, 1]) {
      const tm = new THREE.InstancedMesh(tailGeo, matTail, NINST);
      const tOn = [], tOff = [];
      for (let k = 0; k < NINST; k++) {
        const { x, z } = basePos[k];
        const r = rnd(k * 3.7 + c * 11.3 + (sgn > 0 ? 1.9 : 5.3));
        const a = r * 6.283;
        const s = c ? 1 : -1;
        o.position.set(x + Math.cos(a) * 0.075 * s, sgn * (HY - 0.09), z + Math.sin(a) * 0.075 * s);
        o.rotation.set((rnd(k + c * 2.1) - 0.5) * 0.24, a, (rnd(k * 1.7 + c) - 0.5) * 0.24 + (sgn > 0 ? 0 : Math.PI));
        o.scale.set(1, 0.94 + r * 0.12, 1);
        o.updateMatrix(); tm.setMatrixAt(k, o.matrix); tOn.push(o.matrix.clone());
        o.scale.setScalar(0.0001); o.updateMatrix(); tOff.push(o.matrix.clone());
        tm.setColorAt(k, cA.set(0xD9A38E).lerp(cB.set(0xEFD0C0), r));
      }
      tm.instanceMatrix.needsUpdate = true; tm.instanceColor.needsUpdate = true;
      tm.frustumCulled = false;
      slabGroup.add(tm);
      instSets.push({ mesh: tm, on: tOn, off: tOff, base: basePos });
    }
  }
}

/* ── core / seam / glycerol bands / pick proxies ────────────────────────── */
const unitBox = new THREE.BoxGeometry(1, 1, 1);
const coreMat = new THREE.MeshPhongMaterial({ color: 0xC08D7B, specular: 0x30221d, shininess: 5 });
const seamMat = new THREE.MeshBasicMaterial({ color: 0xAE7A69 });
const bandMat = new THREE.MeshBasicMaterial({ color: 0xE8A33D, transparent: true, opacity: 0.92 });
const pickMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });

function mkBox(mat) { const m = new THREE.Mesh(unitBox, mat); slabGroup.add(m); return m; }
const coreA = mkBox(coreMat), coreB = mkBox(coreMat);
const seamA = mkBox(seamMat), seamB = mkBox(seamMat);
const bandA = [mkBox(bandMat), mkBox(bandMat)], bandB = [mkBox(bandMat), mkBox(bandMat)];
const bands = [...bandA, ...bandB];
