const proxTop = mkBox(pickMat), proxBot = mkBox(pickMat);

function setBox(m, x0, x1, z0, z1, yc, yh) {
  m.position.set((x0 + x1) / 2, yc, (z0 + z1) / 2);
  m.scale.set(Math.max(0.001, x1 - x0), yh, Math.max(0.001, z1 - z0));
}

let cutT = 0.60, cutTarget = 0.60;

function applyCut(t) {
  const xCut = XG1 - 2.7 * t;
  const zCut = ZG1 - 1.9 * t;

  for (const set of instSets) {
    for (let k = 0; k < NINST; k++) {
      const b = set.base[k];
      set.mesh.setMatrixAt(k, (b.x > xCut && b.z > zCut) ? set.off[k] : set.on[k]);
    }
    set.mesh.instanceMatrix.needsUpdate = true;
  }

  const xA1 = Math.min(xCut, XG1) - IN;
  setBox(coreA, XG0 + IN, xA1, ZG0 + IN, ZG1 - IN, 0, 2 * CYH);
  setBox(seamA, XG0 + IN - 0.10, xA1 + 0.10, ZG0 + IN - 0.10, ZG1 - IN + 0.10, 0, 0.05);
  bandA.forEach((b, i) => setBox(b, XG0 + IN - 0.09, xA1 + 0.09,
    ZG0 + IN - 0.09, ZG1 - IN + 0.09, (i ? -1 : 1) * 0.99, 0.10));

  setBox(proxTop, XG0, xA1 + IN, ZG0, ZG1 - 0.02, HY, 0.36);
  setBox(proxBot, XG0, xA1 + IN, ZG0, ZG1 - 0.02, -HY, 0.36);

  const showB = t > 0.012 && (zCut - IN) > (ZG0 + IN);
