  if (showB) {
    setBox(coreB, xA1 - 0.04, XG1 - IN, ZG0 + IN, zCut - IN, 0, 2 * CYH);
    setBox(seamB, xA1 - 0.04, XG1 - IN + 0.10, ZG0 + IN - 0.10, zCut - IN + 0.10, 0, 0.05);
    bandB.forEach((b, i) => setBox(b, xA1 - 0.04, XG1 - IN + 0.09,
      ZG0 + IN - 0.09, zCut - IN + 0.09, (i ? -1 : 1) * 0.99, 0.10));
  }
  bandB.forEach(b => b.visible = showB && (hl === 'glycerol'));

  const lab = document.getElementById('cutVal');
  if (lab) lab.textContent = t.toFixed(2);
}

/* ── formula panel (flat line art, billboarded) ─────────────────────────── */
const FX = 5.6, FY = 0.45, FS = 0.82;
const formula = new THREE.Group();
