scene.add(formula);

function SB() { this.v = []; }
SB.prototype.tri = function (a, b, c) {
  this.v.push(a[0] - FX, a[1] - FY, 0, b[0] - FX, b[1] - FY, 0, c[0] - FX, c[1] - FY, 0);
};
SB.prototype.quad = function (a, b, c, d) { this.tri(a, b, c); this.tri(a, c, d); };
SB.prototype.seg = function (x1, y1, x2, y2, w) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1;
  const nx = -dy / L * w / 2, ny = dx / L * w / 2;
  this.quad([x1 + nx, y1 + ny], [x2 + nx, y2 + ny], [x2 - nx, y2 - ny], [x1 - nx, y1 - ny]);
};
SB.prototype.dbl = function (x, y, angDeg, r0, r1, gap, w) {
  const a = angDeg * Math.PI / 180, ux = Math.cos(a), uy = Math.sin(a), px = -uy, py = ux;
  for (const s of [-1, 1]) {
    this.seg(x + ux * r0 + px * gap * s, y + uy * r0 + py * gap * s,
      x + ux * r1 + px * gap * s, y + uy * r1 + py * gap * s, w);
  }
};
SB.prototype.arrow = function (x1, y1, x2, y2, w, hw, hl2) {
  const dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  const bx = x2 - ux * hl2, by = y2 - uy * hl2;
  this.seg(x1, y1, bx, by, w);
  this.tri([x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]);
};
/* irregular hand-drawn acyl chain: three offset sine octaves + varying width */
SB.prototype.ribbon = function (x0, x1, y, seed, w) {
  const N = 120, pts = [];
  const A = [0.078, 0.034, 0.015];
  const F = [1.5 + seed * 0.55, 3.0 + seed * 0.9, 5.4 + seed * 0.7];
  const P = [seed * 2.7, 1.2 + seed * 1.9, 2.6 + seed * 0.7];
  for (let i = 0; i <= N; i++) {
    const u = i / N, x = x0 + (x1 - x0) * u;
    let off = 0;
    for (let q = 0; q < 3; q++) off += A[q] * Math.sin(2 * Math.PI * F[q] * u + P[q]);
    off *= (0.40 + 0.60 * Math.sin(Math.PI * u));          // calm the ends, kink the middle
    pts.push([x, y + off]);
  }
  for (let i = 0; i < N; i++) {
    const u = (i + 0.5) / N;
    const ww = w * (0.80 + 0.20 * Math.sin(u * Math.PI * 3.1 + seed * 1.7));
    this.seg(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], ww);
  }
};
SB.prototype.mesh = function (color, order) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(this.v, 3));
  g.computeBoundingSphere(); g.computeBoundingBox();
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity: 1, depthWrite: false
  }));
  m.renderOrder = order || 1;
  formula.add(m);
  return m;
};

