/* ── highlight logic ────────────────────────────────────────────────────── */
const regionMeshes = {
  head: [greenMesh, greenArrow],
  glycerol: [blackMesh],
  tails: [ribbonMesh, magentaArrow]
};
const GLOWCSS = { head: 'rgba(23,160,106,0.9)', glycerol: 'rgba(232,163,61,0.95)', tails: 'rgba(224,33,138,0.85)' };
function setHighlight(h) {
  hl = h;
  for (const r of ['head', 'glycerol', 'tails']) {
    const on = (h === r), dim = (h !== 'none' && !on);
    regionMeshes[r].forEach(m => { m.material.opacity = dim ? 0.20 : 1; });
    glowPlanes[r].material.opacity = on ? 0.18 : 0;
  }
  for (const rec of labelRecs) {
    const on = (hl === rec.region), dim = (hl !== 'none' && !on);
    rec.entry.div.style.opacity = dim ? 0.22 : 1;
    rec.entry.div.style.textShadow = on ? `0 0 8px ${GLOWCSS[rec.region]}` : 'none';
  }
  matHead.color.set((h === 'none' || h === 'head') ? 0xffffff : 0x9aa09c);
  matHead.emissive.set(h === 'head' ? 0x1d7f57 : 0x000000);
  matTail.color.set((h === 'none' || h === 'tails') ? 0xffffff : 0xa8a29d);
  matTail.emissive.set(h === 'tails' ? 0x6d1338 : 0x000000);
  coreMat.color.set((h === 'none' || h === 'tails') ? 0xC08D7B : 0xAAA49E);
  coreMat.emissive.set(h === 'tails' ? 0x430a21 : 0x000000);
  bandA.forEach(b => b.visible = (h === 'glycerol'));
  bandB.forEach(b => b.visible = (h === 'glycerol') && coreB.visible);
  document.querySelectorAll('#partBtns button').forEach(b =>
    b.classList.toggle('active', b.dataset.part === h));
}

