/* size labels so their on-screen pixel size matches the source hierarchy */
(function sizeLabels() {
  const dist = camera.position.distanceTo(formula.position);
  const s = Math.max(0.05, 8 / dist);
  for (const rec of labelRecs) rec.entry.div.style.fontSize = (rec.px / s).toFixed(1) + 'px';
})();

/* ── billboard + tween loop ────────────────────────────────────────────── */
const _wq = new THREE.Quaternion();
function updateBillboard() {
  formula.quaternion.copy(camera.quaternion);
  _wq.copy(camera.quaternion);
  for (const rec of labelRecs) {
    rec.entry.pos.copy(rec.local).applyQuaternion(_wq).add(formula.position);
  }
}
let _last = performance.now(), _playT = 0, playing = false;
(function loop() {
  requestAnimationFrame(loop);
  try {
    const now = performance.now(), dt = Math.min(0.05, (now - _last) / 1000); _last = now;
    if (Math.abs(cutTarget - cutT) > 0.002) {
      cutT += (cutTarget - cutT) * Math.min(1, dt * 5.0);
      applyCut(cutT);
      const sl = document.getElementById('cutaway'); if (sl) sl.value = cutT.toFixed(2);
    }
    if (playing) {
      _playT += dt;
      if (_playT > 5.5) { _playT = 0; goToStep(stepIdx + 1); }
    }
    updateBillboard();
  } catch (e) { /* never stall the figure */ }
})();

